import { Lesson } from '../../types';
import { buildLesson, ChoiceSeed, makeChoices, makeSpeakings, makeWritings, SpeakingSeed, WritingSeed } from './helpers';

const CHOOSE_FORM = 'Listen and choose the correct form.';
const CHOOSE_ANSWER = 'Listen and choose the correct answer.';
const CHOOSE_SENTENCE = 'Listen and choose the correct sentence.';
const SHORT_SPEAKING = 'Listen and answer with a short sentence.';
const TRANSLATE_PT = 'Translate to Portuguese.';
const TYPE_EXACTLY = 'Type exactly what you hear.';
const WRITE_SHORT = 'Write the short answer.';

function choice(
  display: string,
  audio: string,
  options: string[],
  correct: string,
  translation?: string,
  type?: 'multiple-choice' | 'identification',
): ChoiceSeed {
  return { display, audio, options, correct, translation, type };
}

function exact(audio: string, translation?: string): WritingSeed {
  return { audio, display: audio, correct: audio, translation, instruction: TYPE_EXACTLY };
}

function short(display: string, audio: string, correct: string, translation?: string): WritingSeed {
  return { display, audio, correct, translation, instruction: WRITE_SHORT };
}

function speakingFromChoices(seeds: ChoiceSeed[]): SpeakingSeed[] {
  return seeds.map((seed) => ({
    display: seed.display ?? seed.audio,
    audio: seed.audio,
    correct: seed.correct,
    accepted: seed.accepted,
    translation: seed.translation,
  }));
}

function translationsFromChoices(seeds: ChoiceSeed[]): WritingSeed[] {
  return seeds.map((seed) => {
    if (!seed.translation) {
      throw new Error(`Missing translation for "${seed.audio}"`);
    }
    return {
      display: seed.audio,
      audio: seed.audio,
      correct: seed.translation,
      translation: seed.translation,
    };
  });
}

function buildStandardLesson(config: {
  number: number;
  title: string;
  day1Instruction: string;
  day1: ChoiceSeed[];
  day2Instruction: string;
  day2: ChoiceSeed[];
  day3Instruction: string;
  day3: ChoiceSeed[];
  day6Exact: WritingSeed[];
  day6Short: WritingSeed[];
}): Lesson {
  return buildLesson(config.number, config.title, [
    { type: 'practice', exercises: makeChoices(config.day1, config.day1Instruction) },
    { type: 'practice', exercises: makeChoices(config.day2, config.day2Instruction) },
    { type: 'practice', exercises: makeChoices(config.day3, config.day3Instruction) },
    { type: 'practice', exercises: makeSpeakings(speakingFromChoices(config.day3), SHORT_SPEAKING) },
    { type: 'practice', exercises: makeWritings(translationsFromChoices(config.day1.slice(0, 10)), TRANSLATE_PT) },
    { type: 'practice', exercises: [...makeWritings(config.day6Exact, TYPE_EXACTLY), ...makeWritings(config.day6Short, WRITE_SHORT)] },
    {
      type: 'review',
      exercises: [
        ...makeChoices(config.day1.slice(0, 5), config.day1Instruction),
        ...makeChoices(config.day2.slice(0, 5), config.day2Instruction),
        ...makeChoices(config.day3.slice(0, 5), config.day3Instruction),
        ...makeSpeakings(speakingFromChoices(config.day3.slice(0, 5)), SHORT_SPEAKING),
      ],
    },
  ]);
}

